  function batchDetail(options={}){const ret=call('batches'),batch=rows(ret).find(row=>row.batchId===options.batchId);if(ret.status!=='success'||!batch)return '<section class="platform-page fnw-workspace">'+ui.pageHeader('批次业务名单','当前批次不存在或不在有权范围。',button('返回导入批次','openBatches'))+notice(ret.status==='success'?{status:'failed',message:'请从当前有权批次重新打开名单。'}:ret)+'</section>';return recordList({...options,batchId:batch.batchId,batchDetail:true}).replace('<div class="filter-panel">','<div class="fnw-note"><strong>'+e(batch.name||batch.batchId)+'</strong> · '+e(batch.categoryName||batch.categoryId)+' · '+e(time(batch.at))+'</div><div class="filter-panel">');}
