  function selectedResourceOptions(resources,selectedId,placeholder){const list=(resources||[]).map(item=>({...item,id:item.resourceId||item.id,name:item.name||item.label||'未命名执行对象'}));if(selectedId&&!list.some(item=>String(item.id)===String(selectedId)))list.unshift({id:selectedId,name:'原执行对象已失效或不在当前范围，请重新选择'});return selectOptions(list,selectedId,'id','name',placeholder);}
