  function reclassificationPayload(d){if(!d.reclassContext||!d.targetCategoryId)throw Error('请先选择可用目标线索分类。');const reason=value('fnw-reclass-reason').trim();if(!reason)throw Error('请填写调整原因。');return {targetCategoryId:d.targetCategoryId,reason,values:reclassificationValues(d)};}
